    public static Set<Item> register(net.minecraftforge.client.event.ModelRegistryEvent event) {
        StaticItemFamilyRegistration family = new StaticItemFamilyRegistration(descriptors());
        family.register(event);
        MinecraftForge.EVENT_BUS.register(family);
        return family.items();
    }
